    24	    /** Duration in which the item gets fully highlighted */
    25	    highlightStartDuration?: number;
    26	
    27	    /** Delay before the item starts to get un-highlighted */
    28	    highlightEndDelay?: number;
    29	
    30	    /** Duration in which the item gets fully un-highlighted */
    31	    highlightEndDuration?: number;
    32	
    33	    /** Whether the item should be highlighted */
