    36	
    37	/**
    38	 * Returns a highlight style that interpolates the colour, height and opacity giving a fading effect.
    39	 */
    40	export default function useAnimatedHighlightStyle({
    41	    borderRadius,
    42	    shouldHighlight,
    43	    itemEnterDelay = CONST.ANIMATED_HIGHLIGHT_ENTRY_DELAY,
    44	    itemEnterDuration = CONST.ANIMATED_HIGHLIGHT_ENTRY_DURATION,
    45	    highlightStartDelay = CONST.ANIMATED_HIGHLIGHT_START_DELAY,
    46	    highlightStartDuration = CONST.ANIMATED_HIGHLIGHT_START_DURATION,
    47	    highlightEndDelay = CONST.ANIMATED_HIGHLIGHT_END_DELAY,
    48	    highlightEndDuration = CONST.ANIMATED_HIGHLIGHT_END_DURATION,
    49	    height,
    50	}: Props) {
    51	    const [startHighlight, setStartHighlight] = useState(false);
    52	    const repeatableProgress = useSharedValue(0);
    53	    const nonRepeatableProgress = useSharedValue(shouldHighlight ? 0 : 1);
    54	    const {didScreenTransitionEnd} = useScreenWrapperTranstionStatus();
    55	    const theme = useTheme();
    56	
    57	    const highlightBackgroundStyle = useAnimatedStyle(() => ({
    58	        backgroundColor: interpolateColor(repeatableProgress.value, [0, 1], [theme.appBG, theme.border]),
    59	        height: interpolate(nonRepeatableProgress.value, [0, 1], [0, height]),
    60	        opacity: interpolate(nonRepeatableProgress.value, [0, 1], [0, 1]),
    61	        borderRadius,
    62	    }));
    63	
    64	    React.useEffect(() => {
    65	        if (!shouldHighlight || startHighlight) {
    66	            return;
    67	        }
    68	        setStartHighlight(true);
    69	        // We only need to add shouldHighlight as a dependency and adding startHighlight as deps will cause a loop because
    70	        // if shouldHighlight stays at true the above early return will not be executed and this useEffect will be run
    71	        // as long as shouldHighlight is true as we set startHighlight to false in the below useEffect.
    72	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
    73	    }, [shouldHighlight]);
    74	
    75	    React.useEffect(() => {
    76	        if (!startHighlight || !didScreenTransitionEnd) {
    77	            return;
    78	        }
    79	        setStartHighlight(false);
    80	        InteractionManager.runAfterInteractions(() => {
    81	            runOnJS(() => {
    82	                nonRepeatableProgress.value = withDelay(
    83	                    itemEnterDelay,
    84	                    withTiming(1, {duration: itemEnterDuration, easing: Easing.inOut(Easing.ease)}, (finished) => {
    85	                        if (!finished) {
    86	                            return;
    87	                        }
    88	
    89	                        // eslint-disable-next-line react-compiler/react-compiler
    90	                        repeatableProgress.value = withSequence(
    91	                            withDelay(highlightStartDelay, withTiming(1, {duration: highlightStartDuration, easing: Easing.inOut(Easing.ease)})),
    92	                            withDelay(highlightEndDelay, withTiming(0, {duration: highlightEndDuration, easing: Easing.inOut(Easing.ease)})),
    93	                        );
    94	                    }),
    95	                );
    96	            })();
    97	        });
    98	    }, [
    99	        didScreenTransitionEnd,
   100	        startHighlight,
   101	        itemEnterDelay,
   102	        itemEnterDuration,
   103	        highlightStartDelay,
   104	        highlightStartDuration,
   105	        highlightEndDelay,
   106	        highlightEndDuration,
   107	        repeatableProgress,
   108	        nonRepeatableProgress,
   109	    ]);
   110	
   111	    return highlightBackgroundStyle;
   112	}
